#### B. `SplitPaymentModal.tsx`
*   **Ergonomía:** Modal flotante con efecto *Glassmorphism profundo* (`bg-slate-950/80 backdrop-blur-2xl`). Permite asignar montos exactos a diferentes medios de pago (Efectivo, Tarjeta, Cuenta Corriente, MercadoPago).

```tsx
import React, { useState } from 'react';
import { X, DollarSign, CreditCard, Wallet, Check } from 'lucide-react';

interface SplitPaymentModalProps {
  isOpen: boolean;
  onClose: () => void;
  totalAmount: number;
}

export const SplitPaymentModal: React.FC<SplitPaymentModalProps> = ({ isOpen, onClose, totalAmount }) => {
  const [payments, setPayments] = useState([
    { method: 'Efectivo', amount: 20000, icon: DollarSign },
    { method: 'Tarjeta Débito', amount: 22402, icon: CreditCard },
  ]);

  if (!isOpen) return null;

  const paidTotal = payments.reduce((acc, p) => acc + p.amount, 0);
  const remaining = totalAmount - paidTotal;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-md p-4 animate-fadeIn">
      <div className="w-full max-w-2xl rounded-3xl bg-slate-900/90 border border-slate-800 shadow-2xl overflow-hidden backdrop-blur-xl">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-slate-800">
          <div>
            <h2 className="text-lg font-bold text-slate-100">Pago Dividido / Múltiples Formas</h2>
            <p className="text-xs text-slate-400">Asigne montos por cada medio de pago disponible</p>
          </div>
          <button onClick={onClose} className="p-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white transition-all">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Cuerpo */}
        <div className="p-6 space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="p-4 rounded-2xl bg-slate-950/60 border border-slate-800">
              <span className="text-xs text-slate-400">Total a Cubrir</span>
              <p className="text-2xl font-mono font-bold text-slate-100">${totalAmount.toLocaleString()}</p>
            </div>
            <div className={`p-4 rounded-2xl border ${remaining === 0 ? 'bg-emerald-950/30 border-emerald-800/50' : 'bg-amber-950/30 border-amber-800/50'}`}>
              <span className="text-xs text-slate-400">Restante / Vuelto</span>
              <p className={`text-2xl font-mono font-bold ${remaining === 0 ? 'text-emerald-400' : 'text-amber-400'}`}>
                ${Math.abs(remaining).toLocaleString()} {remaining < 0 ? '(Vuelto)' : ''}
              </p>
            </div>
          </div>

          {/* Lista de Pagos Ingresados */}
          <div className="space-y-3">
            {payments.map((p, idx) => {
              const Icon = p.icon;
              return (
                <div key={idx} className="flex items-center justify-between p-3.5 rounded-xl bg-slate-950/40 border border-slate-800">
                  <div className="flex items-center gap-3">
                    <div className="p-2 rounded-lg bg-cyan-500/10 text-cyan-400">
                      <Icon className="w-5 h-5" />
                    </div>
                    <span className="font-medium text-sm text-slate-200">{p.method}</span>
                  </div>
                  <span className="font-mono font-bold text-slate-100 text-base">${p.amount.toLocaleString()}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 bg-slate-950/60 border-t border-slate-800">
          <button onClick={onClose} className="px-5 py-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium text-sm transition-all">
            Cancelar (ESC)
          </button>
          <button 
            disabled={remaining > 0}
            className={`px-6 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${remaining === 0 ? 'bg-cyan-500 hover:bg-cyan-400 text-slate-950 shadow-lg shadow-cyan-500/20' : 'bg-slate-800 text-slate-500 cursor-not-allowed'}`}
          >
            <Check className="w-4 h-4" />
            Confirmar Cobro
          </button>
        </div>

      </div>
    </div>
  );
};
```

